// 足跡地圖：把旅程的「國家」文字對到世界地圖上的國家，算出各洲收集進度
// - 只算已完成、已封存的旅程（和「去過的國家」統計一樣）
// - 國家欄位可填多國（用頓號、逗號或斜線分開）；國家對不到時改用城市欄位再找一次
// - 台灣、香港、澳門各算一個

const CONT = { A: '亞洲', E: '歐洲', N: '北美洲', S: '南美洲', F: '非洲', O: '大洋洲' };
export const CONTINENT_KEYS = Object.keys(CONT);
export const continentName = k => CONT[k];

const norm = s => String(s || '').replace(/臺/g, '台').replace(/\s+/g, '');
let index = null;
function build() {
  const byName = new Map(), info = new Map();
  COUNTRY_TABLE.trim().split('\n').forEach(line => {
    const [cont, id, names] = line.split(' ');
    const list = names.split('|');
    info.set(id, { id, cont, name: list[0] });
    list.forEach(n => byName.set(norm(n), id));
  });
  return (index = { byName, info });
}

export function countryInfo(id) { return (index || build()).info.get(id); }

// 文字 → 國碼陣列（對不到的放在 unmatched）
export function matchPlaces(text) {
  const { byName } = index || build();
  const ids = [], unmatched = [];
  String(text || '').split(/[、,，/／;；&＋+]/).map(norm).filter(Boolean).forEach(p => {
    const id = byName.get(p) || byName.get(p.replace(/(共和國|王國)$/, ''));
    if (id) ids.push(id); else unmatched.push(p);
  });
  return { ids, unmatched };
}

export function worldFootprint(trips) {
  const { info } = index || build();
  const visited = new Map(), unmatched = new Set();
  trips.filter(t => t.status === '已完成' || t.status === '已封存').forEach(t => {
    let m = matchPlaces(t.country);
    if (!m.ids.length && t.city) {
      const c = matchPlaces(t.city);
      if (c.ids.length) m = { ids: c.ids, unmatched: [] };
    }
    m.unmatched.forEach(n => unmatched.add(n));
    new Set(m.ids).forEach(id => visited.set(id, (visited.get(id) || 0) + 1));
  });
  const total = {}, got = {};
  info.forEach(c => { total[c.cont] = (total[c.cont] || 0) + 1; });
  visited.forEach((_, id) => { const c = info.get(id).cont; got[c] = (got[c] || 0) + 1; });
  const continents = CONTINENT_KEYS.map(k => ({ key: k, name: CONT[k], got: got[k] || 0, total: total[k] }));
  return { visited, unmatched: [...unmatched], continents };
}

